class Solution:
    def maxFreeTime(self, eventTime: int, k: int, startTime: List[int], endTime: List[int]) -> int:
        n = len(startTime)

        gaps = []
        prev_end = 0
        for i in range(n):
            gaps.append(startTime[i] - prev_end)
            prev_end = endTime[i]
        gaps.append(eventTime - prev_end)

        window = k + 1
        cur = sum(gaps[:window])
        best = cur

        for i in range(window, len(gaps)):
            cur += gaps[i] - gaps[i - window]
            best = max(best, cur)

        return best
